import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  Box, Paper, Typography, TextField, Button, Grid, FormControl,
  InputLabel, Select, MenuItem, CircularProgress, Alert, Divider
} from '@mui/material';
import SaveIcon from '@mui/icons-material/Save';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import JalaliDatePicker from '../core/components/ui/JalaliDatePicker';
import {
  useEmployee, useCreateEmployee, useUpdateEmployee,
  useDepartments, useJobTitles, useWorkLocations, useInsuranceLists
} from '../core/hooks/useEmployees';

const EmployeeForm = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { id } = useParams();
  const isEdit = Boolean(id);

  // Data queries
  const { data: employee, isLoading: loadingEmployee } = useEmployee(id);
  const { data: departments } = useDepartments();
  const { data: jobTitles } = useJobTitles();
  const { data: workLocations } = useWorkLocations();
  const { data: insuranceLists } = useInsuranceLists();
  const createMutation = useCreateEmployee();
  const updateMutation = useUpdateEmployee();

  const [form, setForm] = useState({
    first_name: '', last_name: '', national_id: '', birth_date: '', birth_place: '',
    gender: '', marital_status: '', children_count: 0, spouse_name: '',
    national_id_serial: '', national_id_place: '', national_id_date: '',
    phone: '', mobile: '', email: '', address: '', postal_code: '',
    emergency_contact_name: '', emergency_contact_phone: '',
    employee_id: '', hire_date: '', probation_end_date: '', official_date: '',
    department: '', job_title: '', work_location: '', insurance_list: '',
    contract_type: '', contract_start_date: '', contract_end_date: '',
    status: 'active', status_change_date: '', work_shift: '', description: '',
  });
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (employee) {
      const e = employee;
      setForm({
        first_name: e.first_name || '', last_name: e.last_name || '', national_id: e.national_id || '',
        birth_date: e.birth_date || '', birth_place: e.birth_place || '',
        gender: e.gender || '', marital_status: e.marital_status || '',
        children_count: e.children_count || 0, spouse_name: e.spouse_name || '',
        national_id_serial: e.national_id_serial || '', national_id_place: e.national_id_place || '',
        national_id_date: e.national_id_date || '',
        phone: e.phone || '', mobile: e.mobile || '', email: e.email || '',
        address: e.address || '', postal_code: e.postal_code || '',
        emergency_contact_name: e.emergency_contact_name || '',
        emergency_contact_phone: e.emergency_contact_phone || '',
        employee_id: e.employee_id || '', hire_date: e.hire_date || '',
        probation_end_date: e.probation_end_date || '', official_date: e.official_date || '',
        department: e.department || '', job_title: e.job_title || '',
        work_location: e.work_location || '', insurance_list: e.insurance_list || '',
        contract_type: e.contract_type || '', contract_start_date: e.contract_start_date || '',
        contract_end_date: e.contract_end_date || '', status: e.status || 'active',
        status_change_date: e.status_change_date || '', work_shift: e.work_shift || '',
        description: e.description || '',
      });
    }
  }, [employee]);

  const handleChange = (field, value) => setForm(prev => ({ ...prev, [field]: value }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSubmitting(true);
    try {
      if (isEdit) {
        await updateMutation.mutateAsync({ id, data: form });
      } else {
        await createMutation.mutateAsync(form);
      }
      navigate('/employees');
    } catch (err) {
      setError(err.response?.data?.detail || t('employees.save_error'));
    } finally {
      setSubmitting(false);
    }
  };

  if (isEdit && loadingEmployee) return <Box sx={{ textAlign: 'center', p: 4 }}><CircularProgress /></Box>;

  const selectField = (label, field, options = [], required = false) => (
    <Grid item xs={12} sm={6} md={4}>
      <FormControl fullWidth size="small" required={required}>
        <InputLabel>{label}</InputLabel>
        <Select value={form[field]} label={label} onChange={(e) => handleChange(field, e.target.value)}>
          {options.map(opt => <MenuItem key={opt.value} value={opt.value}>{opt.label}</MenuItem>)}
        </Select>
      </FormControl>
    </Grid>
  );

  const textField = (label, field, required = false, type = 'text') => (
    <Grid item xs={12} sm={6} md={4}>
      <TextField fullWidth size="small" label={label} type={type} value={form[field] || ''}
        onChange={(e) => handleChange(field, e.target.value)} required={required}
        InputLabelProps={type === 'date' ? { shrink: true } : {}} />
    </Grid>
  );

  const dateField = (label, field) => (
    <Grid item xs={12} sm={6} md={4}>
      <JalaliDatePicker fullWidth label={label} value={form[field]}
        onChange={(gregorian) => handleChange(field, gregorian)} />
    </Grid>
  );

  const GENDERS = [{ value: 'male', label: t('employees.male') }, { value: 'female', label: t('employees.female') }];
  const MARITAL = [{ value: 'single', label: t('employees.single') }, { value: 'married', label: t('employees.married') }, { value: 'divorced', label: t('employees.divorced') }, { value: 'widowed', label: t('employees.widowed') }];
  const CONTRACT = [{ value: 'permanent', label: t('employees.permanent') }, { value: 'temporary', label: t('employees.temporary') }, { value: 'project', label: t('employees.project') }, { value: 'contractor', label: t('employees.contractor') }];
  const STATUSES = [{ value: 'active', label: t('employees.active') }, { value: 'leave', label: t('employees.on_leave') }, { value: 'retired', label: t('employees.retired') }, { value: 'terminated', label: t('employees.terminated') }, { value: 'deceased', label: t('employees.deceased') }];
  const SHIFTS = [{ value: 'morning', label: t('employees.morning') }, { value: 'evening', label: t('employees.evening') }, { value: 'rotating', label: t('employees.rotating') }, { value: 'irregular', label: t('employees.irregular') }];

  const mapOptions = (data) => Array.isArray(data) ? data.map(d => ({ value: d.id, label: d.name })) : [];

  return (
    <Box component="form" onSubmit={handleSubmit}>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 3, gap: 2 }}>
        <Button startIcon={<ArrowBackIcon />} onClick={() => navigate('/employees')}>{t('common.back')}</Button>
        <Typography variant="h4">{isEdit ? t('employees.edit_employee') : t('employees.add_employee')}</Typography>
      </Box>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

      {/* Personal Info */}
      <Paper sx={{ p: 3, mb: 2 }}><Typography variant="h6" gutterBottom>{t('employees.personal_info')}</Typography><Divider sx={{ mb: 2 }} />
        <Grid container spacing={2}>
          {textField(t('employees.first_name'), 'first_name', true)}
          {textField(t('employees.last_name'), 'last_name', true)}
          {textField(t('employees.national_id'), 'national_id', true)}
          {dateField(t('employees.birth_date'), 'birth_date')}
          {textField(t('employees.birth_place'), 'birth_place')}
          {selectField(t('employees.gender'), 'gender', GENDERS, true)}
          {selectField(t('employees.marital_status'), 'marital_status', MARITAL, true)}
          {textField(t('employees.children_count'), 'children_count', false, 'number')}
          {textField(t('employees.spouse_name'), 'spouse_name')}
          {textField(t('employees.national_id_serial'), 'national_id_serial')}
          {textField(t('employees.national_id_place'), 'national_id_place')}
          {dateField(t('employees.national_id_date'), 'national_id_date')}
        </Grid>
      </Paper>

      {/* Contact Info */}
      <Paper sx={{ p: 3, mb: 2 }}><Typography variant="h6" gutterBottom>{t('employees.contact_info')}</Typography><Divider sx={{ mb: 2 }} />
        <Grid container spacing={2}>
          {textField(t('employees.phone'), 'phone')}
          {textField(t('employees.mobile'), 'mobile', true)}
          {textField(t('employees.email'), 'email')}
          {textField(t('employees.address'), 'address')}
          {textField(t('employees.postal_code'), 'postal_code')}
          {textField(t('employees.emergency_contact_name'), 'emergency_contact_name')}
          {textField(t('employees.emergency_contact_phone'), 'emergency_contact_phone')}
        </Grid>
      </Paper>

      {/* Employment Info */}
      <Paper sx={{ p: 3, mb: 2 }}><Typography variant="h6" gutterBottom>{t('employees.employment_info')}</Typography><Divider sx={{ mb: 2 }} />
        <Grid container spacing={2}>
          {textField(t('employees.employee_id'), 'employee_id', true)}
          {dateField(t('employees.hire_date'), 'hire_date')}
          {dateField(t('employees.probation_end_date'), 'probation_end_date')}
          {dateField(t('employees.official_date'), 'official_date')}
          {selectField(t('employees.department'), 'department', mapOptions(departments), true)}
          {selectField(t('employees.job_title'), 'job_title', mapOptions(jobTitles), true)}
          {selectField(t('employees.work_location'), 'work_location', mapOptions(workLocations), true)}
          {selectField(t('employees.insurance_list'), 'insurance_list', mapOptions(insuranceLists), true)}
          {selectField(t('employees.contract_type'), 'contract_type', CONTRACT, true)}
          {dateField(t('employees.contract_start_date'), 'contract_start_date')}
          {dateField(t('employees.contract_end_date'), 'contract_end_date')}
          {selectField(t('employees.status'), 'status', STATUSES)}
          {dateField(t('employees.status_change_date'), 'status_change_date')}
          {selectField(t('employees.work_shift'), 'work_shift', SHIFTS)}
          <Grid item xs={12}>
            <TextField fullWidth size="small" label={t('employees.description')} multiline rows={3}
              value={form.description} onChange={(e) => handleChange('description', e.target.value)} />
          </Grid>
        </Grid>
      </Paper>

      <Box sx={{ display: 'flex', gap: 2, justifyContent: 'flex-end' }}>
        <Button variant="outlined" onClick={() => navigate('/employees')}>{t('common.cancel')}</Button>
        <Button type="submit" variant="contained" startIcon={<SaveIcon />} disabled={submitting}>
          {submitting ? <CircularProgress size={20} /> : t('common.save')}
        </Button>
      </Box>
    </Box>
  );
};

export default EmployeeForm;
